// THE LAB'S CREATURES: their pictures, generated by code like everything in
// textures.js (whose helpers these use). The behaviour is in creatures.js.
//
// THE LURCHER: a hunched, man-sized mutant, pale and stitched together, its
// small head sunk between massive shoulders. Its right arm is the experiment
// that took: swollen, greenish, with bigger claws. Its eyes glow, so in a
// dark corner you see them before you see it.
//
// Same layout as a robot (ROBOT_FRAMES): frames[view][pose], 64x64, feet on
// the bottom row, the torso across row 32 where shots land (combat.js).
// Poses: stand, walk1, walk2, and two attack poses seen only from the front:
//   rear    the wind-up: reared up, arms raised, mouth open. Your warning.
//   lunge   the lunge: crouched, arms flung wide and forward

const FLESH = [178, 160, 146];
const FLESH_DARK = [104, 86, 80];
const MUTANT = [132, 150, 98];      // the swollen arm
const VEIN = [92, 118, 76];
const CLAW = [222, 214, 188];
const MAW = [74, 14, 20];
const STAPLE = [60, 64, 72];
const CREATURE_EYE = [150, 255, 90];
const ICHOR = [70, 116, 40];

// Mottled skin: the base colour, unevenly blotched, with the odd green vein.
function skin(colour, x, y, shade, seed) {
  // Veins only in a few patches of skin, or they break up into speckle.
  const vein = noise(x >> 3, y >> 3, seed + 3) > 0.7 && Math.abs(Math.sin(x * 0.55 + y * 0.32 + 4 * noise(x >> 3, y >> 3, seed))) < 0.12;
  const blotch = 0.9 + 0.12 * noise(x >> 2, y >> 2, seed + 1) + 0.04 * noise(x, y, seed + 2);
  return brighten(vein ? VEIN : colour, shade * blotch);
}

// Is (dx, y) inside the ellipse at (cx, cy) with radii rx, ry? Returns how
// far out from the centre it is (0 middle, 1 edge), or null if outside.
function inEllipse(dx, y, cx, cy, rx, ry) {
  const ux = (dx - cx) / rx, uy = (y + 0.5 - cy) / ry;
  const r = ux * ux + uy * uy;
  return r < 1 ? Math.sqrt(r) : null;
}

// One arm: shoulder -> elbow -> hand, a knot of a fist, and three claws.
// The forearm is thicker than the upper arm (that's where the swipe comes
// from). `big` is the mutant arm. clawsUp points the claws upwards (reared).
function lurcherArm(x, y, dx, shoulder, elbow, hand, big, clawsUp, shade) {
  const s = big ? 1.35 : 1;
  const colour = big ? MUTANT : FLESH;
  const r = 3.6 * s;
  for (const k of [-1, 0, 1]) {
    const tipY = clawsUp ? hand[1] - r - 5 * s : hand[1] + r + 5 * s;
    const baseY = clawsUp ? hand[1] - r * 0.5 : hand[1] + r * 0.5;
    const d = segmentDistance(dx, y, hand[0] + k * 2.2 * s, baseY, hand[0] + k * 3.4 * s, tipY);
    if (d < 1.1) return brighten(CLAW, shade * (1.15 - 0.3 * d));
  }
  const fist = inEllipse(dx, y, hand[0], hand[1], r, r);
  if (fist !== null) return skin(colour, x, y, shade * (1.1 - 0.45 * fist), 71);
  for (const [a, b, w] of [[elbow, hand, 3.2 * s], [shoulder, elbow, 2.8 * s]]) {
    const d = segmentDistance(dx, y, a[0], a[1], b[0], b[1]);
    if (d < w) return skin(colour, x, y, shade * (1.1 - 0.5 * d / w), 72);
  }
  return null;
}

// A short, bowed leg and a broad foot with toe claws.
function lurcherLeg(x, y, dx, hip, knee, ankle, shade) {
  if (y >= ankle[1] && y < ankle[1] + 4 && Math.abs(dx - ankle[0]) < 5) {
    if (y === ankle[1] + 3 && (Math.floor(dx - ankle[0] + 5) % 3) === 0) return brighten(CLAW, shade);
    return skin(FLESH_DARK, x, y, shade, 73);
  }
  for (const [a, b, w] of [[hip, knee, 4], [knee, ankle, 3]]) {
    const d = segmentDistance(dx, y, a[0], a[1], b[0], b[1]);
    if (d < w) return skin(FLESH_DARK, x, y, shade * (1.2 - 0.5 * d / w), 74);
  }
  return null;
}

// From the front or the back. From the front its right (mutant) arm is on
// YOUR left; from behind, on your right.
function lurcherFrontBackShape(view, pose) {
  const front = view === 'front';
  const feed = pose === 'feed';
  const drop = pose === 'lunge' ? 3 : feed ? 8 : 0; // it crouches into the lunge, and low over a meal
  const open = pose === 'rear' || pose === 'lunge';
  return (x, y) => {
    const dx = x + 0.5 - 32;
    const yy = y - drop;

    // Arms first: they're in front of the body or out to the sides.
    for (const side of [-1, 1]) {
      const big = front ? side < 0 : side > 0;
      const sway = pose === 'walk1' ? side * 2 : pose === 'walk2' ? -side * 2 : 0;
      let shoulder = [side * 12, 23 + drop], elbow, hand;
      if (pose === 'rear') { elbow = [side * 21, 13]; hand = [side * 17, 7]; }
      else if (pose === 'lunge') { elbow = [side * 22, 29]; hand = [side * 25, 37]; }
      else if (feed) { elbow = [side * 15, 41]; hand = [side * 8, 55]; } // tearing at what's on the floor
      else { elbow = [side * 18, 37]; hand = [side * 18 + sway * 0.5, 50 + Math.abs(sway) * 0.5]; }
      const arm = lurcherArm(x, y, dx, shoulder, elbow, hand, big, pose === 'rear', 1);
      if (arm) return arm;
    }

    // The head, sunk low between the shoulders.
    const head = inEllipse(dx, yy, 0, 19, 5.5, 5);
    if (head !== null) {
      if (front) {
        const eyeRow = yy >= 17 && yy < 19;
        if (eyeRow && Math.abs(dx) > 1.2 && Math.abs(dx) < 4) {
          if (feed) return brighten(CREATURE_EYE, 0.35); // eating, the eyes dim
          return glowing(open ? [230, 255, 200] : CREATURE_EYE); // rearing, the eyes flare
        }
        const mouthTop = 21, mouthBottom = open ? 25 : 23;
        if (yy >= mouthTop && yy < mouthBottom && Math.abs(dx) < (open ? 4 : 3)) {
          const teeth = (yy === mouthTop || (open && yy === mouthBottom - 1)) && Math.floor(dx + 8) % 2 === 0;
          return teeth ? CLAW : MAW;
        }
      } else if (yy >= 15 && yy < 22 && Math.abs(dx) < 0.8) {
        return brighten(FLESH_DARK, 0.9); // a ridge over the skull
      }
      return skin(FLESH, x, y, 1.1 - 0.4 * head, 75);
    }

    // The torso: a hump of shoulder, narrowing to the waist.
    if (yy >= 17 && yy < 45) {
      const halfW = yy < 24 ? 9 + (yy - 17) * 0.85 : 15 - (yy - 24) * 0.3;
      if (Math.abs(dx) < halfW) {
        if (front) {
          // A surgical scar down the chest, held with staples.
          if (yy >= 26 && yy < 42 && yy % 3 === 0 && Math.abs(dx) < 2.5) return STAPLE;
          if (yy >= 26 && yy < 42 && Math.abs(dx) < 0.6) return brighten(MAW, 1.4);
        } else {
          // The spine, a row of knobs, and three feeding ports beside it,
          // still glowing with whatever they pumped into it.
          if (Math.abs(dx) < 2 && yy >= 20 && yy < 43 && yy % 4 < 3) return brighten(CLAW, 0.8 - 0.15 * Math.abs(dx));
          for (const py of [25, 32, 39]) {
            const p = Math.hypot(dx - 6, yy + 0.5 - py);
            if (p < 1.5) return glowing(CREATURE_EYE);
            if (p < 2.5) return STAPLE;
          }
        }
        return skin(FLESH, x, y, roundShade(dx / halfW), 76);
      }
    }

    // Legs: the stepping one lifts its foot.
    for (const side of [-1, 1]) {
      const lift = (pose === 'walk1' && side < 0) || (pose === 'walk2' && side > 0) ? 3 : 0;
      const knee = feed ? [side * 13, 56] : [side * 10, 52 + drop * 0.5 - lift];
      const leg = lurcherLeg(x, y, dx, [side * 6, Math.min(43 + drop, 50)], knee, [side * 8, 59 - lift], 1);
      if (leg) return leg;
    }
    return null;
  };
}

// Side on, facing right: the hunch shows here, head thrust forward. The near
// arm hangs in front of the body; the swollen far arm pokes out behind it.
function lurcherSideShape(pose) {
  if (pose === 'feed') {
    const stand = lurcherSideShape('stand');
    return (x, y) => {
      if (y < 5) return null;
      const t = stand(x, y - 5);
      return t && t[3] === true ? brighten(CREATURE_EYE, 0.35) : t; // the only glow is the eye: dimmed
    };
  }
  const swing = pose === 'walk1' ? 4 : pose === 'walk2' ? -4 : 0;
  return (x, y) => {
    const dx = x + 0.5 - 32;

    const near = lurcherArm(x, y, dx, [3, 24], [7 + swing * 0.3, 38], [11 + swing * 0.6, 50], false, false, 1);
    if (near) return near;

    const head = inEllipse(dx, y, 11, 24, 5.5, 4.5);
    if (head !== null) {
      if (dx >= 12.5 && dx < 15 && y >= 22 && y < 24) return glowing(CREATURE_EYE);
      if (dx >= 12 && dx < 16.5 && y === 26) return MAW;
      return skin(FLESH, x, y, 1.1 - 0.4 * head, 77);
    }

    // The hunched back, and the narrower hips under it.
    const hump = inEllipse(dx, y, -2, 29, 11.5, 10.5);
    if (hump !== null) {
      // Knobs of spine along the top of the back.
      if (dx < 2 && hump > 0.82 && y < 28 && Math.floor(dx + 20) % 4 < 2) return brighten(CLAW, 0.8);
      return skin(FLESH, x, y, 1.15 - 0.45 * hump, 78);
    }
    const hips = inEllipse(dx, y, -4, 38, 8, 6.5);
    if (hips !== null) return skin(FLESH, x, y, 0.85 - 0.3 * hips, 82);

    const far = lurcherArm(x, y, dx, [-3, 24], [-1 - swing * 0.3, 38], [3 - swing * 0.6, 50], true, false, 0.6);
    if (far) return far;

    for (const [s, shade] of [[swing, 1], [-swing, 0.6]]) {
      const leg = lurcherLeg(x, y, dx, [-6, 41], [1 + s * 0.6, 50], [-4 + s, 59], shade);
      if (leg) return leg;
    }
    return null;
  };
}

function makeLurcherFrames() {
  const bake = (shape) => makeTexture(FLESH, shape);
  const poses = (make) => ({ stand: make('stand'), walk1: make('walk1'), walk2: make('walk2'), feed: make('feed') });
  const front = (pose) => bake(lurcherFrontBackShape('front', pose));
  return {
    front: { ...poses(front), rear: front('rear'), lunge: front('lunge') },
    back:  poses((pose) => bake(lurcherFrontBackShape('back', pose))),
    right: poses((pose) => bake(lurcherSideShape(pose))),
    left:  poses((pose) => bake(mirroredShape(lurcherSideShape(pose), true))),
  };
}

// A dead lurcher: a slumped heap of flesh in a pool of green ichor, the
// mutant arm flung out, claws up.
function makeLurcherCorpse() {
  return makeTexture(FLESH, (x, y) => {
    const dx = x + 0.5 - 32;
    const arm = lurcherArm(x, y, dx, [6, 52], [16, 55], [24, 52], true, true, 0.85);
    if (arm) return arm;
    if (y >= 46) {
      const halfW = 11 + (y - 46) * 0.9;
      if (Math.abs(dx) < halfW && y < 61) {
        if (y >= 51 && y < 53 && dx > -9 && dx < -6) return [40, 60, 30]; // an eye, gone dark
        return skin(FLESH, x, y, 0.55 + 0.4 * noise(x >> 2, y >> 1, 79), 80);
      }
    }
    if (y >= 59 && Math.abs(dx) < 26 - (63 - y) * 2) return brighten(ICHOR, 0.8 + 0.3 * noise(x, y, 81));
    return null;
  });
}

// THE SPITTER: lanky and stooped, on a long neck, with a huge throat sac of
// acid under its jaw that glows through the skin, so you can pick it out
// across a dark room. Aiming, the sac swells and brightens; firing, its
// mouth gapes. On its back, two acid glands, glowing too: shots there count
// double (backHits), so get round behind it.
// Poses as a robot's: stand, walk1, walk2, and front aim and fire.
const SPITTER_SKIN = [160, 150, 128];
const SPITTER_DARK = [92, 84, 70];
const ACID = [120, 235, 70];
const ACID_HOT = [220, 255, 170];

// The sac: an ellipse of glowing, mottled acid seen through the skin.
function sacTexel(x, y, dx, cx, cy, rx, ry, hot) {
  const e = inEllipse(dx, y, cx, cy, rx, ry);
  if (e === null) return null;
  if (e > 0.85) return skin(SPITTER_DARK, x, y, 1, 90); // the skin round its edge
  const swirl = noise(x >> 1, y >> 1, 91);
  return glowing(mix(hot ? ACID_HOT : ACID, [40, 90, 20], 0.5 * e + 0.25 * swirl));
}

function spitterFrontBackShape(view, pose) {
  const front = view === 'front';
  const aiming = pose === 'aim' || pose === 'fire';
  return (x, y) => {
    const dx = x + 0.5 - 32;

    // Thin arms, hanging long, with small hooked claws.
    for (const side of [-1, 1]) {
      const sway = pose === 'walk1' ? side * 2 : pose === 'walk2' ? -side * 2 : 0;
      const hand = [side * 13 + sway * 0.5, 50];
      for (const k of [-1, 1]) {
        const d = segmentDistance(dx, y, hand[0] + k * 1.5, hand[1] + 1, hand[0] + k * 2.3, hand[1] + 6);
        if (d < 0.9) return brighten(CLAW, 1.1 - 0.3 * d);
      }
      for (const [a, b, w] of [[[side * 9, 27], [side * 14, 39], 2.2], [[side * 14, 39], hand, 2]]) {
        const d = segmentDistance(dx, y, a[0], a[1], b[0], b[1]);
        if (d < w) return skin(SPITTER_SKIN, x, y, 1.1 - 0.5 * d / w, 92);
      }
    }

    // The head, high up on its neck: four small eyes, and a mouth that gapes to fire.
    const head = inEllipse(dx, y, 0, 12, 4.5, 4);
    if (head !== null) {
      if (front) {
        if (y === 11 && [-3.5, -1.5, 1.5, 3.5].some((ex) => Math.abs(dx - ex) < 0.8)) return glowing(aiming ? ACID_HOT : ACID);
        if (pose === 'fire' && y >= 13 && y < 17 && Math.abs(dx) < 2.5) return glowing(ACID_HOT); // the spray leaving its mouth
        if (y === 14 && Math.abs(dx) < 2) return MAW;
      }
      return skin(SPITTER_SKIN, x, y, 1.1 - 0.4 * head, 93);
    }

    // The throat sac. From behind you just see it bulging out either side.
    const sac = aiming ? sacTexel(x, y, dx, 0, 21, 8, 6.5, true) : sacTexel(x, y, dx, 0, 20.5, 6, 5, false);
    if (sac && (front || Math.abs(dx) > 4)) return sac;
    if (Math.abs(dx) < 2 && y >= 15 && y < 27) return skin(SPITTER_SKIN, x, y, 0.9, 94); // the neck

    // A narrow chest, tapering to a pinched waist.
    if (y >= 26 && y < 45) {
      const halfW = 9 - (y - 26) * 0.18;
      if (Math.abs(dx) < halfW) {
        if (!front) {
          for (const gx of [-4, 4]) {                      // the acid glands: shoot them
            const g = Math.hypot(dx - gx, y + 0.5 - 31);
            if (g < 2.4) return glowing(mix(ACID, ACID_HOT, 1 - g / 2.4));
            if (g < 3.3) return skin(SPITTER_DARK, x, y, 1, 95);
          }
          if (Math.abs(dx) < 1 && y % 3 < 2) return brighten(CLAW, 0.75); // spine
        } else if (y < 40 && Math.abs(dx) > 1.5 && Math.abs(dx) < halfW - 1.5 && Math.floor(y - 28 - Math.abs(dx) * 0.4) % 4 === 0) {
          return brighten(SPITTER_DARK, 0.95);                 // its ribs showing, curving down from the breastbone
        }
        return skin(SPITTER_SKIN, x, y, roundShade(dx / halfW), 96);
      }
    }

    for (const side of [-1, 1]) {
      const lift = (pose === 'walk1' && side < 0) || (pose === 'walk2' && side > 0) ? 3 : 0;
      for (const [a, b, w] of [[[side * 4, 44], [side * 8, 52 - lift], 2.6], [[side * 8, 52 - lift], [side * 6, 60 - lift], 2.2]]) {
        const d = segmentDistance(dx, y, a[0], a[1], b[0], b[1]);
        if (d < w) return skin(SPITTER_DARK, x, y, 1.15 - 0.5 * d / w, 97);
      }
      if (y >= 60 - lift && y < 63 - lift && Math.abs(dx - side * 6) < 3.5) return skin(SPITTER_DARK, x, y, 0.9, 98);
    }
    return null;
  };
}

// Side on, facing right: the stoop shows, its neck reaching forward and the
// sac hanging under its jaw, a gland glowing on its back.
function spitterSideShape(pose) {
  const swing = pose === 'walk1' ? 4 : pose === 'walk2' ? -4 : 0;
  return (x, y) => {
    const dx = x + 0.5 - 32;
    for (const [a, b, w] of [[[2, 28], [5 + swing * 0.3, 40], 2.2], [[5 + swing * 0.3, 40], [7 + swing * 0.6, 51], 2]]) {
      const d = segmentDistance(dx, y, a[0], a[1], b[0], b[1]);
      if (d < w) return skin(SPITTER_SKIN, x, y, 1.1 - 0.5 * d / w, 99);
    }
    const head = inEllipse(dx, y, 11, 13, 5, 3.5);
    if (head !== null) {
      if (dx >= 12.5 && dx < 14.5 && y === 12) return glowing(ACID);
      return skin(SPITTER_SKIN, x, y, 1.1 - 0.4 * head, 100);
    }
    const sac = sacTexel(x, y, dx, 9, 19.5, 4.5, 4.5, false);
    if (sac) return sac;
    if (segmentDistance(dx, y, 0, 30, 9, 15) < 2.4) return skin(SPITTER_SKIN, x, y, 0.95, 101); // the neck
    const g = Math.hypot(dx + 7, y + 0.5 - 30);
    if (g < 2.4) return glowing(ACID);
    const body = inEllipse(dx, y, -3, 35, 9, 9.5);
    if (body !== null) return skin(SPITTER_SKIN, x, y, 1.15 - 0.45 * body, 102);
    for (const [s, shade] of [[swing, 1], [-swing, 0.6]]) {
      for (const [a, b, w] of [[[-4, 42], [1 + s * 0.6, 51], 2.6], [[1 + s * 0.6, 51], [-3 + s, 60], 2.2]]) {
        const d = segmentDistance(dx, y, a[0], a[1], b[0], b[1]);
        if (d < w) return skin(SPITTER_DARK, x, y, shade * (1.15 - 0.5 * d / w), 103);
      }
      if (y >= 60 && y < 63 && dx >= -6 + s && dx < 2 + s) return skin(SPITTER_DARK, x, y, 0.9 * shade, 104);
    }
    return null;
  };
}

function makeSpitterFrames() {
  const bake = (shape) => makeTexture(SPITTER_SKIN, shape);
  const poses = (make) => ({ stand: make('stand'), walk1: make('walk1'), walk2: make('walk2') });
  const front = (pose) => bake(spitterFrontBackShape('front', pose));
  return {
    front: { ...poses(front), aim: front('aim'), fire: front('fire') },
    back:  poses((pose) => bake(spitterFrontBackShape('back', pose))),
    right: poses((pose) => bake(spitterSideShape(pose))),
    left:  poses((pose) => bake(mirroredShape(spitterSideShape(pose), true))),
  };
}

// A dead spitter: a heap with its sac burst, acid soaking the floor round it.
function makeSpitterCorpse() {
  return makeTexture(SPITTER_SKIN, (x, y) => {
    const dx = x + 0.5 - 32;
    const sac = inEllipse(dx, y, 12, 55, 6, 3.5);
    if (sac !== null) return brighten(SPITTER_DARK, 0.7 + 0.3 * sac); // emptied
    if (y >= 49 && y < 61 && Math.abs(dx + 2) < 8 + (y - 49) * 0.7) return skin(SPITTER_SKIN, x, y, 0.5 + 0.4 * noise(x >> 2, y >> 1, 105), 106);
    if (y >= 59 && Math.abs(dx) < 27 - (63 - y) * 2.5) return glowing(mix(ACID, [30, 60, 10], 0.55 + 0.3 * noise(x, y, 107)));
    return null;
  });
}

// A GLOB of acid in flight (acid.js): a glowing ball with a hot core, at
// eye height in the texture; acid.js raises and lowers it along its arc.
const ACID_GLOB_TEXTURE = makeTexture(ACID, (x, y) => {
  const r = Math.hypot(x + 0.5 - 32, y + 0.5 - 32);
  if (r < 2) return glowing(ACID_HOT);
  if (r < 4.5) return glowing(ACID);
  if (r < 5.5 && noise(x, y, 108) < 0.5) return glowing([60, 140, 30]);
  return null;
});

// Where a glob will land: a thin ring flat on the floor (the bottom rows of
// the texture are the floor), two frames so it pulses.
const ACID_TARGET_FRAMES = [0, 1].map((f) => makeTexture(ACID, (x, y) => {
  const ex = (x + 0.5 - 32) / (14 - f * 3), ey = (y + 0.5 - 61) / (2.2 - f * 0.5);
  const r = Math.hypot(ex, ey);
  return r > 0.8 && r < 1 ? glowing(f ? ACID_HOT : ACID) : null;
}));

// THE LARVAE (larvae.js): pale, segmented grubs the size of a cat, low on
// the floor, mandibles first, with glowing spots down their sides. They look
// the same from every side (a swarm, like the drones), so just three frames:
// two of scuttling, and the leap, legs splayed and jaws wide.
// They sit on the bottom rows of the texture, which is the floor, so the
// shot test aims at LARVA_AIM_ROW rather than eye height (combat.js).
const LARVA_SKIN = [204, 194, 160];
const LARVA_AIM_ROW = 55;
function larvaShape(frame) {
  const leap = frame === 2;
  return (x, y) => {
    const dx = x + 0.5 - 32;
    const cy = leap ? 52 : 56;
    // Legs: little spikes along the bottom, out of step frame to frame.
    for (let k = -3; k <= 3; k++) {
      if (k === 0) continue;
      const lx = k * 3.6, tip = leap ? [lx * 1.5, cy + 9] : [lx * 1.2 + ((k + frame) % 2 ? 1.5 : -1.5), 62.5];
      if (segmentDistance(dx, y, lx, cy + 3, tip[0], tip[1]) < 0.8) return brighten(SPITTER_DARK, 0.9);
    }
    // Mandibles, opening wide to leap.
    for (const side of [-1, 1]) {
      const tip = leap ? [side * 7, cy - 6] : [side * 3, cy + 4];
      if (segmentDistance(dx, y, side * 3, cy - 1, tip[0], tip[1]) < 1) return brighten(CLAW, 0.95);
    }
    const head = inEllipse(dx, y, 0, cy, 5, 4.2);
    if (head !== null) {
      if (y === cy - 2 && Math.abs(Math.abs(dx) - 2) < 0.8) return glowing(ACID);
      if (leap && y >= cy && y < cy + 2 && Math.abs(dx) < 2.5) return MAW;
      return skin(LARVA_SKIN, x, y, 1.1 - 0.35 * head, 109);
    }
    const body = inEllipse(dx, y, 0, cy, 13, 6);
    if (body !== null) {
      if (Math.floor(Math.abs(dx) + 1) % 4 === 0) return brighten(LARVA_SKIN, 0.6);     // the segments
      if (Math.abs(y + 0.5 - cy) < 1 && Math.floor(Math.abs(dx) + 1) % 4 === 2 && Math.abs(dx) > 6) return glowing([90, 200, 60]);
      return skin(LARVA_SKIN, x, y, 1.1 - 0.5 * body, 110);
    }
    return null;
  };
}
const LARVA_FRAMES = [0, 1, 2].map((f) => makeTexture(LARVA_SKIN, larvaShape(f)));


// THE STALKER: lean and long-limbed, taller than you, on digitigrade legs,
// with long blade fingers. Its skin bends the light: in the dark it's almost
// nothing, a shimmer at its edges and two cold eye-glints; under a lamp, or
// in your muzzle flash, you see all of it. So its frames come in
// STALKER_LEVELS of visibility, and enemies.js picks one by the light where
// it stands (stalkerVisibility, stalker.js).
// Poses: stand, walk1, walk2, and front 'slash' (a blade arm raised).
const STALKER_SKIN = [124, 116, 144];
const STALKER_DARK = [64, 58, 80];
const STALKER_EYE = [190, 230, 255];
const STALKER_BLADE = [200, 205, 220];
// How opaque its skin is at each visibility level (0 = dark ... 3 = lit).
// Level 0 is a shimmer: faint skin, a brighter rim. The eyes always glow.
const STALKER_ALPHA = [12, 80, 170, 255];
const STALKER_RIM_ALPHA = [70, 120, 200, 255];
const STALKER_SHIMMER = [[46, 50, 66], [70, 74, 98]]; // the glowing rim's colour at levels 0 and 1

// Its skin: bands that ripple like heat haze, which is the "light-bending".
function stalkerSkin(x, y, shade) {
  const band = 0.75 + 0.3 * Math.sin((x + y * 0.6) * 0.9 + 3 * noise(x >> 2, y >> 2, 150));
  return brighten(STALKER_SKIN, shade * band);
}

// A thin limb from a to b, then on to c: shaded down its length.
function stalkerLimb(dx, y, x, pts, w, shade) {
  for (let n = 0; n + 1 < pts.length; n++) {
    const d = segmentDistance(dx, y, pts[n][0], pts[n][1], pts[n + 1][0], pts[n + 1][1]);
    if (d < w) return stalkerSkin(x, y, shade * (1.1 - 0.5 * d / w));
  }
  return null;
}

// Three long blades from the hand, pointing along (ux, uy).
function stalkerBlades(dx, y, hand, ux, uy) {
  for (const k of [-1, 0, 1]) {
    const tx = hand[0] + ux * 9 + k * 1.8 * Math.abs(uy), ty = hand[1] + uy * 9 + k * 1.8 * Math.abs(ux);
    if (segmentDistance(dx, y, hand[0], hand[1], tx, ty) < 0.7) return STALKER_BLADE;
  }
  return null;
}

function stalkerFrontBackShape(view, pose) {
  const front = view === 'front';
  return (x, y) => {
    const dx = x + 0.5 - 32;
    for (const side of [-1, 1]) {
      const sway = pose === 'walk1' ? side * 2 : pose === 'walk2' ? -side * 2 : 0;
      const raised = pose === 'slash' && side > 0;
      const shoulder = [side * 7, 21];
      const elbow = raised ? [side * 14, 12] : [side * 12, 33];
      const hand = raised ? [side * 9, 4] : [side * 13 + sway * 0.5, 45];
      const blade = raised ? stalkerBlades(dx, y, hand, -0.3 * side, -1) : stalkerBlades(dx, y, hand, 0.1 * side, 1);
      if (blade) return blade;
      const arm = stalkerLimb(dx, y, x, [shoulder, elbow, hand], 1.6, 1);
      if (arm) return arm;
    }
    const head = inEllipse(dx, y, 0, 12, 3.5, 5);
    if (head !== null) {
      if (front && y >= 11 && y < 13 && Math.abs(dx) > 0.8 && Math.abs(dx) < 2.8) return glowing(STALKER_EYE);
      return stalkerSkin(x, y, 1.15 - 0.4 * head);
    }
    if (y >= 17 && y < 20 && Math.abs(dx) < 1.3) return stalkerSkin(x, y, 0.8); // the neck
    if (y >= 20 && y < 41) {
      const halfW = 7 - (y - 20) * 0.17;
      if (Math.abs(dx) < halfW) {
        if (front && y >= 23 && y < 34 && (y - 23) % 3 === 0 && Math.abs(dx) > 1) return brighten(STALKER_DARK, 0.9); // ribs
        if (!front && Math.abs(dx) < 1 && y % 3 < 2) return brighten(STALKER_SKIN, 1.3); // spine
        return stalkerSkin(x, y, roundShade(dx / halfW));
      }
    }
    for (const side of [-1, 1]) {
      const lift = (pose === 'walk1' && side < 0) || (pose === 'walk2' && side > 0) ? 3 : 0;
      const leg = stalkerLimb(dx, y, x, [[side * 3.5, 40], [side * 6.5, 48 - lift], [side * 3, 55 - lift], [side * 5, 61 - lift]], 1.7, 0.95);
      if (leg) return leg;
    }
    return null;
  };
}

// Side on, facing right: leaning forward, head out front, arms reaching.
function stalkerSideShape(pose) {
  const swing = pose === 'walk1' ? 4 : pose === 'walk2' ? -4 : 0;
  return (x, y) => {
    const dx = x + 0.5 - 32;
    const nearHand = [12 + swing * 0.6, 42];
    const blade = stalkerBlades(dx, y, nearHand, 0.5, 0.85);
    if (blade) return blade;
    const near = stalkerLimb(dx, y, x, [[3, 22], [9 + swing * 0.3, 32], nearHand], 1.6, 1);
    if (near) return near;
    const head = inEllipse(dx, y, 9, 15, 5, 3.5);
    if (head !== null) {
      if (dx >= 10.5 && dx < 13 && y >= 14 && y < 16) return glowing(STALKER_EYE);
      return stalkerSkin(x, y, 1.15 - 0.4 * head);
    }
    if (segmentDistance(dx, y, 1, 21, 6, 16) < 1.3) return stalkerSkin(x, y, 0.85); // the neck
    const body = segmentDistance(dx, y, 1, 22, -3, 40);
    if (body < 4.5) return stalkerSkin(x, y, 1.1 - 0.5 * body / 4.5);
    const far = stalkerLimb(dx, y, x, [[1, 22], [6 - swing * 0.3, 32], [10 - swing * 0.6, 42]], 1.5, 0.6);
    if (far) return far;
    for (const [s, shade] of [[swing, 1], [-swing, 0.6]]) {
      const leg = stalkerLimb(dx, y, x, [[-3, 40], [3 + s * 0.5, 47], [-3 + s, 54], [1 + s, 61]], 1.7, shade);
      if (leg) return leg;
    }
    return null;
  };
}

// Bake a shape at one visibility level: skin and blades go see-through by
// STALKER_ALPHA, the rim (a texel with empty space beside it) a little
// less, the eyes stay lit. Nothing goes fully transparent where the body
// is, so you can still shoot what you can't see. In the dark (levels 0 and
// 1) every other rim texel GLOWS faintly instead: the darkness would
// swallow a merely see-through rim, but a glowing one ignores the light,
// so you see a broken shimmer of an outline, and the eyes.
function bakeStalker(shape, level) {
  const at = (x, y) => (x < 0 || y < 0 || x >= TEX_SIZE || y >= TEX_SIZE ? null : shape(x, y));
  return makeTexture(STALKER_SKIN, (x, y) => {
    const t = at(x, y);
    if (t === null) return null;
    if (t[3] === true || level === 3) return t;
    const rim = at(x - 1, y) === null || at(x + 1, y) === null || at(x, y - 1) === null || at(x, y + 1) === null;
    if (rim && level < 2 && noise(x, y, 155) < 0.5) return glowing(STALKER_SHIMMER[level]);
    return seeThrough(t, rim ? STALKER_RIM_ALPHA[level] : STALKER_ALPHA[level]);
  });
}

function makeStalkerFrames(level) {
  const bake = (shape) => bakeStalker(shape, level);
  const poses = (make) => ({ stand: make('stand'), walk1: make('walk1'), walk2: make('walk2') });
  const front = (pose) => bake(stalkerFrontBackShape('front', pose));
  return {
    front: { ...poses(front), slash: front('slash') },
    back:  poses((pose) => bake(stalkerFrontBackShape('back', pose))),
    right: poses((pose) => bake(stalkerSideShape(pose))),
    left:  poses((pose) => bake(mirroredShape(stalkerSideShape(pose), true))),
  };
}
const STALKER_FRAMES = [0, 1, 2, 3].map(makeStalkerFrames);

// Dead, its skin stops bending the light: a tangle of long limbs, fully seen.
function makeStalkerCorpse() {
  return makeTexture(STALKER_SKIN, (x, y) => {
    const dx = x + 0.5 - 32;
    for (const [a, b] of [[[-20, 60], [-4, 55]], [[-4, 55], [14, 58]], [[14, 58], [24, 52]], [[0, 56], [-12, 50]], [[-12, 50], [-22, 53]]]) {
      if (segmentDistance(dx, y, a[0], a[1], b[0], b[1]) < 1.8) return stalkerSkin(x, y, 0.7);
    }
    const body = inEllipse(dx, y, 2, 58, 9, 3.5);
    if (body !== null) return stalkerSkin(x, y, 0.9 - 0.3 * body);
    if (y >= 58 && y < 60 && dx > 10 && dx < 12.5) return [40, 50, 60]; // an eye, gone dark
    if (y >= 61 && Math.abs(dx) < 18) return brighten(ICHOR, 0.6 + 0.3 * noise(x, y, 151));
    return null;
  });
}

// A body eaten clean (feeding.js): a ribcage, a skull, some long bones.
const BONE = [214, 204, 178];
const BONES_TEXTURE = makeTexture(BONE, (x, y) => {
  const dx = x + 0.5 - 32;
  const skull = inEllipse(dx, y, -12, 56, 4, 3.5);
  if (skull !== null) return y >= 56 && y < 58 && Math.abs(Math.abs(dx + 12) - 1.6) < 0.8 ? [30, 24, 20] : brighten(BONE, 1.05 - 0.3 * skull);
  for (let r = 0; r < 4; r++) { // ribs: arcs over a spine
    const cx = -3 + r * 4;
    if (Math.abs(Math.hypot(dx - cx, (y - 61) * 1.4) - 5) < 0.7 && y < 61) return brighten(BONE, 0.9);
  }
  if (y >= 60 && y < 62 && dx > -6 && dx < 14) return brighten(BONE, 0.8); // the spine
  if (segmentDistance(dx, y, 14, 61, 26, 58) < 1 || segmentDistance(dx, y, -20, 62, -28, 59) < 1) return BONE;
  if (y >= 62 && Math.abs(dx) < 20) return brighten(ICHOR, 0.45);
  return null;
});

// A body burnt to ash (a blast, or acid): a black heap with a few embers.
const ASH_TEXTURE = makeTexture([40, 36, 32], (x, y) => {
  const dx = x + 0.5 - 32;
  if (y < 52) return null;
  const halfW = (y - 52) * 2.2 + 4;
  if (Math.abs(dx) >= halfW || Math.abs(dx) > 22) return null;
  if (noise(x, y, 152) < 0.04) return glowing([255, 120 + Math.floor(noise(x, y, 153) * 80), 30]);
  return brighten([46, 42, 38], 0.6 + 0.6 * noise(x >> 1, y, 154));
});

// THE BROOD MOTHER (brood.js): what the breeding programme was for. A small
// head and torso with clawed forelimbs, on top of an enormous translucent
// BELLY, lit green from within, with curled young moving inside it. She
// fills her whole square, so she reads as far bigger than anything else.
// She's rooted in a fleshy nest. Poses: stand, and 'swell' (front only:
// she always faces you once she's awake), the belly stretched and blazing,
// splitting along the bottom. The belly is her weak spot: BROOD_BELLY is
// its ellipse in the front pictures, for combat.js's double-damage test.
const BROOD_SKIN = [190, 170, 168];
const BROOD_DARK = [96, 76, 80];
const BELLY_GLOW = [120, 220, 90];
const BROOD_BELLY = { cx: 32, cy: 43, rx: 22, ry: 15 };

// Inside the belly: the green light, brightest at the middle, with the dark
// curled shapes of young in it (they shift between frames: `seed`).
function bellyTexel(x, y, dx, r, swell, seed) {
  // A wet highlight up and to the left: it's taut and shiny.
  if (Math.hypot(dx + 9, y + 0.5 - 35) < 2.2 && !swell) return glowing([220, 255, 200]);
  // Veins wandering over the skin.
  if (r > 0.25 && Math.abs(Math.sin(dx * 0.35 + 3 * noise(x >> 3, y >> 3, 174)) * 6 - (y - 43)) < 0.55) return brighten(VEIN, 0.6);
  // The young: curled shapes of different sizes, each turned its own way.
  for (let k = 0; k < 4; k++) {
    const yx = -13 + k * 8.5 + 3 * noise(k, seed, 160), yy = 40 + 7 * noise(k, seed, 161) - (k % 2) * 3;
    const size = 2.5 + 1.8 * noise(k, seed, 175);
    const d = Math.hypot(dx - yx, y + 0.5 - yy);
    const a = Math.atan2(y + 0.5 - yy, dx - yx) + 6.3 * noise(k, seed, 176);
    if (Math.abs(d - size) < 1.0 && Math.sin(a) > -0.5) return glowing(brighten(BELLY_GLOW, 0.22)); // the curled body
    if (d < size * 0.45 && Math.sin(a + 1) > 0.3) return glowing(brighten(BELLY_GLOW, 0.28));     // its head, tucked in
  }
  if (r > 0.88) return skin(BROOD_SKIN, x, y, 0.75, 162); // the stretched rim of skin
  if (swell && y > 52 && Math.abs(dx + 4 * Math.sin(y)) < 1.2) return glowing([230, 255, 200]); // splitting
  return glowing(brighten(BELLY_GLOW, (swell ? 0.95 : 0.6) - 0.35 * r + 0.08 * noise(x >> 1, y >> 1, 163 + seed)));
}

function broodFrontShape(pose) {
  const swell = pose === 'swell';
  const b = swell ? { ...BROOD_BELLY, rx: BROOD_BELLY.rx + 3, ry: BROOD_BELLY.ry + 2 } : BROOD_BELLY;
  return (x, y) => {
    const dx = x + 0.5 - 32;
    // Forelimbs, braced on the floor either side of the belly.
    for (const side of [-1, 1]) {
      const pts = [[side * 7, 21], [side * 21, 25], [side * 28, 58]];
      for (let n = 0; n < 2; n++) {
        const w = n === 0 ? 3.6 : 3.0; // thick, heavy limbs: they carry all that weight
        const d = segmentDistance(dx, y, pts[n][0], pts[n][1], pts[n + 1][0], pts[n + 1][1]);
        if (d < w) return skin(BROOD_SKIN, x, y, 1.05 - 0.45 * d / w, 164);
      }
      for (const k of [-1, 1]) if (segmentDistance(dx, y, side * 28, 58, side * 28 + k * 3, 62) < 0.8) return CLAW;
    }
    const belly = inEllipse(dx, y, b.cx - 32, b.cy, b.rx, b.ry);
    if (belly !== null) return bellyTexel(x, y, dx, belly, swell, swell ? 1 : 0);
    const torso = inEllipse(dx, y, 0, 23, 11, 9);
    if (torso !== null) return skin(BROOD_SKIN, x, y, 1.15 - 0.45 * torso, 165);
    const head = inEllipse(dx, y, 0, 12, 5, 4.5);
    if (head !== null) {
      if (y >= 10 && y < 12 && [-3, -1, 1, 3].some((ex) => Math.abs(dx - ex) < 0.7)) return glowing(CREATURE_EYE); // four eyes
      if (y >= 14 && y < 16 && Math.abs(dx) < 2.5) return swell ? MAW : brighten(BROOD_DARK, 0.8);
      return skin(BROOD_SKIN, x, y, 1.1 - 0.4 * head, 166);
    }
    if (y >= 56 && Math.abs(dx) < 30 - (63 - y) * 1.5) return skin(BROOD_DARK, x, y, 0.9, 167); // the nest she's rooted in
    return null;
  };
}

// Behind her: a hunched back with a ridge of spines and clusters of eggs.
function broodBackShape() {
  return (x, y) => {
    const dx = x + 0.5 - 32;
    for (const [ex, ey] of [[-12, 34], [13, 38], [-6, 46], [8, 28]]) {
      const e = Math.hypot(dx - ex, y + 0.5 - ey);
      if (e < 3.5) return glowing(brighten(BELLY_GLOW, 0.5 - 0.1 * e)); // eggs on her back
    }
    const back = inEllipse(dx, y, 0, 40, 24, 20);
    if (back !== null) {
      if (Math.abs(dx) < 1.5 && y < 40 && y % 4 < 2) return brighten(CLAW, 0.75); // spines
      return skin(BROOD_SKIN, x, y, 1.1 - 0.5 * back, 168);
    }
    const head = inEllipse(dx, y, 0, 18, 5, 4.5);
    if (head !== null) return skin(BROOD_SKIN, x, y, 0.95 - 0.4 * head, 169);
    if (y >= 56 && Math.abs(dx) < 30 - (63 - y) * 1.5) return skin(BROOD_DARK, x, y, 0.9, 167);
    return null;
  };
}

// Side on, facing right: the belly hangs forward, the torso rears over it.
function broodSideShape() {
  return (x, y) => {
    const dx = x + 0.5 - 32;
    if (segmentDistance(dx, y, 6, 22, 16, 30) < 2.2 || segmentDistance(dx, y, 16, 30, 22, 58) < 1.8) return skin(BROOD_SKIN, x, y, 1, 164);
    const head = inEllipse(dx, y, 8, 14, 5, 4);
    if (head !== null) {
      if (dx >= 10 && dx < 12.5 && y >= 12 && y < 14) return glowing(CREATURE_EYE);
      return skin(BROOD_SKIN, x, y, 1.1 - 0.4 * head, 166);
    }
    const belly = inEllipse(dx, y, 4, 44, 20, 14);
    if (belly !== null) return bellyTexel(x, y, dx - 4, belly, false, 2);
    const back = inEllipse(dx, y, -10, 38, 14, 18);
    if (back !== null) return skin(BROOD_SKIN, x, y, 1.1 - 0.5 * back, 168);
    const torso = inEllipse(dx, y, 2, 24, 7, 8);
    if (torso !== null) return skin(BROOD_SKIN, x, y, 1.1 - 0.45 * torso, 165);
    if (y >= 56 && Math.abs(dx) < 30 - (63 - y) * 1.5) return skin(BROOD_DARK, x, y, 0.9, 167);
    return null;
  };
}

function makeBroodFrames() {
  const bake = (shape) => makeTexture(BROOD_SKIN, shape);
  const side = bake(broodSideShape());
  return {
    front: { stand: bake(broodFrontShape('stand')), swell: bake(broodFrontShape('swell')) },
    back:  { stand: bake(broodBackShape()) },
    right: { stand: side },
    left:  { stand: bake(mirroredShape(broodSideShape(), true)) },
  };
}

// Dead: the belly burst and slumped flat, dark now, the limbs splayed.
function makeBroodCorpse() {
  return makeTexture(BROOD_SKIN, (x, y) => {
    const dx = x + 0.5 - 32;
    for (const side of [-1, 1]) if (segmentDistance(dx, y, side * 10, 52, side * 29, 60) < 2) return skin(BROOD_SKIN, x, y, 0.7, 170);
    const heap = inEllipse(dx, y, 0, 57, 24, 7);
    if (heap !== null) {
      if (heap < 0.6 && noise(x >> 1, y, 171) < 0.5) return brighten(BELLY_GLOW, 0.25); // what's left inside, gone dark
      return skin(BROOD_SKIN, x, y, 0.8 - 0.3 * heap, 172);
    }
    if (y >= 61 && Math.abs(dx) < 30) return brighten(ICHOR, 0.7 + 0.3 * noise(x, y, 173));
    return null;
  });
}

ROBOT_FRAMES.lurcher = makeLurcherFrames();
ROBOT_FRAMES.spitter = makeSpitterFrames();
ROBOT_FRAMES.brood = makeBroodFrames();
ROBOT_FRAMES.stalker = STALKER_FRAMES[3]; // fully seen: the default (the debug map, the load check)
// What each type leaves behind (enemies.js). Robots leave the robot wreck.
const CORPSE_TEXTURES = { lurcher: makeLurcherCorpse(), spitter: makeSpitterCorpse(), stalker: makeStalkerCorpse(), brood: makeBroodCorpse() };
